{
  "verdict": "request_changes",
  "summary": "Candidate code fails to preserve original relative order for tickets with equal priority.",
  "findings": [
    {
      "finding_id": "STABLE_ORDER_01",
      "file": "candidate.py",
      "line_start": 2,
      "line_end": 2,
      "severity": "high",
      "description": "The implementation sorts tickets by ascending priority and then reverses the list. This reverse operation breaks the stability guarantee required by the specification for tickets with equal priority, causing them to appear in reverse of their original order.",
      "evidence": "For input [(\"t1\", 1), (\"t2\", 1), (\"t3\", 2)], the function returns [\"t3\", \"t2\", \"t1\"], whereas the specification requires [\"t3\", \"t1\", \"t2\"]."
    }
  ]
}
